(function($){var options={xaxis:{category:null},yaxis:{category:null}};function processRawData(plot,series,data,datapoints){var xCategory=series.xaxis.options.mode=="category",yCategory=series.yaxis.options.mode=="category";if(!(xCategory||yCategory))return;var format=datapoints.format;if(!format){var s=series;format=[];format.push({x:true,number:true,required:true});format.push({y:true,number:true,required:true});if(s.bars.show||s.lines.show&&s.lines.fill){var autoscale=!!(s.bars.show&&s.bars.zero||s.lines.show&&s.lines.zero);format.push({y:true,number:true,required:false,defaultValue:0,autoscale:autoscale});if(s.bars.horizontal){delete format[format.length-1].y;format[format.length-1].x=true}}datapoints.format=format}for(var m=0;m<format.length;++m){if(format[m].x&&xCategory)format[m].number=false;if(format[m].y&&yCategory)format[m].number=false}}function getNextIndex(category){var index=-1;for(var v in category)if(category[v]>index)index=category[v];return index+1}function categoryTickGenerator(axis){var res=[];for(var label in axis.category){var v=axis.category[label];if(v>=axis.min&&v<=axis.max)res.push([v,label])}res.sort(function(a,b){return a[0]-b[0]});return res}function setupCategoryForAxis(series,axis,datapoints){if(series[axis].options.mode!="category")return;if(!series[axis].category){var c={},o=series[axis].options.category||{};if($.isArray(o)){for(var i=0;i<o.length;++i)c[o[i]]=i}else{for(var v in o)c[v]=o[v]}series[axis].category=c}if(!series[axis].options.ticks)series[axis].options.ticks=categoryTickGenerator;transformPointsOnAxis(datapoints,axis,series[axis].category)}function transformPointsOnAxis(datapoints,axis,category){var points=datapoints.points,ps=datapoints.pointsize,format=datapoints.format,formatColumn=axis.charAt(0),index=getNextIndex(category);for(var i=0;i<points.length;i+=ps){if(points[i]==null)continue;for(var m=0;m<ps;++m){var val=points[i+m];if(val==null||!format[m][formatColumn])continue;if(!(val in category)){category[val]=index;++index}points[i+m]=category[val]}}}function processDatapoints(plot,series,datapoints){setupCategoryForAxis(series,"xaxis",datapoints);setupCategoryForAxis(series,"yaxis",datapoints)}function init(plot){plot.hooks.processRawData.push(processRawData);plot.hooks.processDatapoints.push(processDatapoints)}$.plot.plugins.push({init:init,options:options,name:"category",version:"1.0"})})(jQuery);